{"code": "import numpy as np
import pandas as pd

class PriorModel:
    def __init__(self, seed=0):
        self.seed = seed
        self.prior = None

    def fit(self, train, target):
        y = train[target]
        self.prior = y.mean()
        return self

    def predict_proba(self, X):
        # Return probabilities for two classes: [prob_negative, prob_positive]
        prob_positive = self.prior
        prob_negative = 1 - self.prior
        return np.full((len(X), 2), [prob_negative, prob_positive])

def fit(train: pd.DataFrame, target: str, seed: int) -> object:
    model = PriorModel(seed=seed)
    model.fit(train, target)
    return model

def predict(model: object, X: pd.DataFrame) -> np.ndarray:
    # model.predict_proba returns [prob_class0, prob_class1]
    return model.predict_proba(X)[:, 1]", "note": "Run 4: Prior model (always predict training prevalence) to test if sandbox works."}
